    {
        "name": "Value Migration",
        "category": "Market Profile",
        "sub_category": "Multi-Session Analysis",
        "description": "The directional shift of the Value Area from one session to the next — indicates directional trend or distribution.",
        "definition": "Consistent upward migration of Value Area (Higher VAH, Higher VAL, Higher POC) across sessions confirms bullish trend. Consistent downward migration confirms bearish trend. Overlapping Value Areas indicate balanced, range-bound conditions.",
        "market_relevance": "NIFTY multi-session Value Migration is computed in Phase 4. Consistent upward value migration is a key bullish regime signal for Phase 10 (Regime Engine). Phase 16 uses value migration direction as a high-weight input.",
        "conditions": {"applicable_when": ["trend identification", "multi-day analysis"], "timeframe": ["Daily", "Weekly"]},
    },
